methods='''    String rialText(double v){return financeMoney(v);}\n    String balanceText(double v){if(v>0)return "🔴 بدهکار: "+rialText(v);if(v<0)return "🟢 طلبکار: "+rialText(Math.abs(v));return "🟢 تسویه";}\n    void financeReport(){frame("گزارش مالی و صندوق",true);managerDrawer();section("صندوق ساختمان","نمای کلی دریافتی‌ها، هزینه‌ها و بدهی واحدها");callFinanceReport("manager_finance_report",new JSONObject(),j->{double income=j.optDouble("totalPaid"),charges=j.optDouble("totalCharges"),repairs=j.optDouble("totalRepairs"),pending=j.optDouble("totalPending");double balance=charges+repairs-income;LinearLayout h=new LinearLayout(this);h.setOrientation(LinearLayout.VERTICAL);h.setPadding(dp(18),dp(16),dp(18),dp(16));h.setBackground(grad(navy,teal,24));h.addView(tv("موجودی خالص / قابل وصول",13,Color.rgb(205,231,229)));TextView bv=tv(rialText(-balance),25,white);bv.setTypeface(Typeface.DEFAULT,Typeface.BOLD);h.addView(bv);h.addView(tv(balance<=0?"وضعیت صندوق مثبت / بدون کسری":"کسری قابل وصول از واحدها: "+rialText(balance),12,white));content.addView(h,new LinearLayout.LayoutParams(-1,dp(118)));content.addView(gap(12));statRow("کل شارژ و هزینه",rialText(charges),"کل تعمیرات",rialText(repairs));statRow("پرداخت تأییدشده",rialText(income),"در انتظار تأیید",rialText(pending));section("وضعیت واحدها","برای هر واحد گزارش تسویه مستقل بگیرید");JSONArray rows=j.optJSONArray("rows");double debt=0,credit=0;if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject q=rows.optJSONObject(i);if(q==null)continue;double bal=q.optDouble("balance");if(bal>0)debt+=bal;if(bal<0)credit+=-bal;unitFinanceCard(q);}statRow("مجموع بدهی واحدها",rialText(debt),"مجموع طلب واحدها",rialText(credit));Button hb=btn("📜 سوابق تسویه واحدها",navy);content.addView(hb,new LinearLayout.LayoutParams(-1,dp(52)));hb.setOnClickListener(v->settlementHistory());boolean show=j.optJSONObject("settings")!=null&&j.optJSONObject("settings").optBoolean("show_unit_debts_to_residents");Button sb=btn("⚙ تنظیمات نمایش بدهی سایر واحدها",blue);content.addView(gap(8));content.addView(sb,new LinearLayout.LayoutParams(-1,dp(52)));sb.setOnClickListener(v->financeSettings(show));Button share=btn("↗ اشتراک‌گذاری گزارش مالی",teal);content.addView(gap(8));content.addView(share,new LinearLayout.LayoutParams(-1,dp(52)));share.setOnClickListener(v->shareFinanceReport(j));});}\n    void unitFinanceCard(JSONObject q){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(14),dp(11),dp(14),dp(11));c.setBackground(box(white,18));TextView h=tv("واحد "+q.optString("unit_no")+"  •  "+q.optString("resident_name","-"),15,navy);h.setTypeface(Typeface.DEFAULT,Typeface.BOLD);c.addView(h,new LinearLayout.LayoutParams(-1,dp(34)));c.addView(tv("تعهد: "+rialText(q.optDouble("total_due"))+"  •  پرداخت: "+rialText(q.optDouble("paid")),12,muted),new LinearLayout.LayoutParams(-1,dp(30)));TextView st=tv(balanceText(q.optDouble("balance")),13,q.optDouble("balance")>0?red:green);st.setTypeface(Typeface.DEFAULT,Typeface.BOLD);c.addView(st,new LinearLayout.LayoutParams(-1,dp(30)));LinearLayout row=new LinearLayout(this);Button settle=btn("🧾 تسویه واحد",gold),detail=btn("جزئیات",blue);row.addView(settle,new LinearLayout.LayoutParams(0,dp(45),1));row.addView(detail,new LinearLayout.LayoutParams(0,dp(45),1));c.addView(row);content.addView(c,new LinearLayout.LayoutParams(-1,dp(151)));content.addView(gap(9));settle.setOnClickListener(v->settlementDialog(q));detail.setOnClickListener(v->settlementDialog(q));}\n    void settlementDialog(JSONObject q){double bal=q.optDouble("balance");String status=bal>0?"بدهکار":bal<0?"طلبکار":"تسویه کامل";String msg="واحد "+q.optString("unit_no")+"\\n\\nشارژ و هزینه: "+rialText(q.optDouble("charges"))+"\\nتعمیرات: "+rialText(q.optDouble("repairs"))+"\\nمجموع تعهد: "+rialText(q.optDouble("total_due"))+"\\nپرداخت تأییدشده: "+rialText(q.optDouble("paid"))+"\\nدر انتظار تأیید: "+rialText(q.optDouble("pending"))+"\\n\\nنتیجه: "+status+"\\n"+balanceText(bal);EditText note=input("یادداشت تسویه (اختیاری)");LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(10),0,dp(10),0);l.addView(tv(msg,14,navy),new LinearLayout.LayoutParams(-1,dp(245)));l.addView(note,new LinearLayout.LayoutParams(-1,dp(54)));new AlertDialog.Builder(this).setTitle("تسویه حساب واحد "+q.optString("unit_no")).setView(l).setNegativeButton("بستن",null).setPositiveButton("ثبت تسویه و ذخیره سابقه",(d,w)->callFinanceReport("create_unit_settlement",new JSONObject().put("unit_id",q.optString("unit_id")).put("note",note.getText().toString()),z->toast("گزارش تسویه ذخیره شد"))).show();}\n    void settlementHistory(){frame("سوابق تسویه واحدها",true);managerDrawer();section("سوابق تسویه","هر تسویه سابقه مستقل دارد");callFinanceReport("unit_settlement_history",new JSONObject(),j->{JSONArray a=j.optJSONArray("items");if(a==null||a.length()==0){empty("هنوز تسویه‌ای ثبت نشده است");return;}for(int i=0;i<a.length();i++){JSONObject q=a.optJSONObject(i);if(q==null)continue;JSONObject u=q.optJSONObject("units");String unit=u==null?q.optString("unit_id"):u.optString("unit_no");LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(14),dp(12),dp(14),dp(12));c.setBackground(box(white,18));c.addView(tv("واحد "+unit+"  •  "+q.optString("resident_name","-"),15,navy));c.addView(tv("تاریخ: "+financeDate(q.optString("settled_at")),12,muted));c.addView(tv(balanceText(q.optDouble("balance_rial")),13,q.optDouble("balance_rial")>0?red:green));c.addView(tv("تعهد: "+rialText(q.optDouble("total_charges_rial")+q.optDouble("total_repairs_rial"))+"  •  پرداخت: "+rialText(q.optDouble("total_paid_rial")),12,muted));content.addView(c,new LinearLayout.LayoutParams(-1,dp(125)));content.addView(gap(9));}});}\n    void financeSettings(boolean current){final Switch sw=new Switch(this);sw.setText("نمایش بدهی سایر واحدها برای ساکنین");sw.setTextSize(15);sw.setTextColor(navy);sw.setChecked(current);TextView info=tv("در حالت فعال، ساکنین فقط شماره واحد و مبلغ بدهی یا طلب را می‌بینند؛ فیش و جزئیات پرداخت سایر واحدها نمایش داده نمی‌شود.",12,muted);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(10),0,dp(10),0);l.addView(sw,new LinearLayout.LayoutParams(-1,dp(62)));l.addView(info,new LinearLayout.LayoutParams(-1,dp(80)));new AlertDialog.Builder(this).setTitle("تنظیمات حریم مالی").setView(l).setNegativeButton("لغو",null).setPositiveButton("ذخیره",(d,w)->callFinanceReport("set_show_unit_debts",new JSONObject().put("enabled",sw.isChecked()),z->toast("تنظیمات ذخیره شد"))).show();}\n    void residentFinanceReport(){frame("وضعیت مالی ساختمان",true);residentDrawer();callFinanceReport("resident_finance_report",new JSONObject(),j->{section("صندوق ساختمان","خلاصه وضعیت مالی ساختمان");JSONObject f=j.optJSONObject("fund");if(f!=null){double net=f.optDouble("totalCharges")+f.optDouble("totalRepairs")-f.optDouble("totalPaid");statRow("کل دریافتی",rialText(f.optDouble("totalPaid")),"کل هزینه",rialText(f.optDouble("totalCharges")+f.optDouble("totalRepairs")));stat("موجودی خالص / قابل وصول",rialText(-net),net>0?red:green);}JSONObject me=j.optJSONObject("me");if(me!=null){section("وضعیت واحد من",null);statRow("تعهد من",rialText(me.optDouble("total_due")),"پرداخت من",rialText(me.optDouble("paid")));stat("بدهی / طلب واحد من",balanceText(me.optDouble("balance")),me.optDouble("balance")>0?red:green);}if(j.optBoolean("show_unit_debts")){section("وضعیت واحدها","طبق تنظیم مدیر ساختمان");JSONArray a=j.optJSONArray("unit_debts");if(a!=null)for(int i=0;i<a.length();i++){JSONObject q=a.optJSONObject(i);if(q!=null)content.addView(tv("واحد "+q.optString("unit_no")+"  •  "+balanceText(q.optDouble("balance")),14,q.optDouble("balance")>0?red:green),new LinearLayout.LayoutParams(-1,dp(48)));}}});}\n    void shareFinanceReport(JSONObject j){try{StringBuilder s=new StringBuilder("گزارش مالی ساختمان\\n\\n");s.append("کل دریافتی: ").append(rialText(j.optDouble("totalPaid"))).append("\\n");s.append("کل هزینه: ").append(rialText(j.optDouble("totalCharges")+j.optDouble("totalRepairs"))).append("\\n");JSONArray a=j.optJSONArray("rows");if(a!=null){s.append("\\nوضعیت واحدها:\\n");for(int i=0;i<a.length();i++){JSONObject q=a.optJSONObject(i);if(q!=null)s.append("واحد ").append(q.optString("unit_no")).append(" : ").append(balanceText(q.optDouble("balance"))).append("\\n");}}Intent in=new Intent(Intent.ACTION_SEND);in.setType("text/plain");in.putExtra(Intent.EXTRA_TEXT,s.toString());startActivity(Intent.createChooser(in,"اشتراک گزارش مالی"));}catch(Exception e){toast("اشتراک گزارش انجام نشد");}}\n'''
if 'void financeReport(){' not in s:s=s.replace('    void managerDrawer(){',methods+'    void managerDrawer(){',1)
